def area(p,names):
 return abs(sum(p[a][0]*p[b][1]-p[b][0]*p[a][1] for a,b in poly(names)))/2
def degrees(p,a,o,b):
 u=subv(p[a],p[o]);v=subv(p[b],p[o]);return math.degrees(math.acos(max(-1,min(1,sum(x*y for x,y in zip(u,v))/math.hypot(*u)/math.hypot(*v)))))
def ac(p,a,o,b):return ang(a,o,b,degrees(p,a,o,b))
def pair(p,scale=.7,shift=(10,0),names=None):
 names=names or list(p)
 for name in names:p[name+'1']=[shift[i]+scale*p[name][i] for i in (0,1)]
 return p
def simchecks(a,b,c,x,y,z,k):return [ratio(a,b,x,y,k),ratio(a,c,x,z,k),ratio(b,c,y,z,k)]
def add(n,part,condition,answer,steps,p,v,views=None,**kw):
 RAW[(n,part)]=deepcopy(p)
 labs={k:k.replace('1','₁') for k in p if '1' in k and not k.startswith('_')};labs.update(kw.pop('labels',{}))
 B.add(n,part,condition,answer,steps,p,v,views,labels=labs,printed=[186 if n<=715 else 187 if n<=725 else 188],**kw)
 # The common helper reverses y, whereas the viewer also negates y for SVG.
 # Restore the author's conventional y-up geometry, notably the vertical poles241.
 for xyz in B.models[-1]['model']['points'].values():xyz[1]=round(80-xyz[1],9)
 for offset in B.models[-1]['model']['labelOffsets'].values():offset[1]=-offset[1]

