add(711,'single','Диагональ AC трапеции ABCD делит её на два подобных треугольника. Докажите, что AC² =a·b, где a и b — основания трапеции.','AC² =AD·BC =a·b.',[
 R('Какие углы уже равны из параллельности?','Обозначим основания AD =a и BC =b. Так как AD ∥BC, ∠DAC =∠ACB. Сопоставим эти равные углы в подобных треугольниках ADC и CBA.','Накрест лежащие углы при секущей AC.',[25,64]),
 R('Как исключить неверное соответствие сторон?','Если при этом D соответствовала бы B, то сторона AC соответствовала бы самой CA. Коэффициент равнялся бы 1, а AD =BC. Но у трапеции с ровно одной парой параллельных сторон основания не равны: равные параллельные противоположные стороны дали бы параллелограмм. Поэтому D соответствует A, а C — B.','Два возможных соответствия после выбора одной вершины; признак параллелограмма.',[49,50,64]),
 R('Какую пропорцию записать?','Итак, △ADC ∼△CAB: AD соответствует CA, а AC — CB. Получаем AD/AC =AC/BC. Умножение на AC·BC даёт AC² =AD·BC =ab.','Пропорциональность сходственных сторон.',64)],p,v,[f,f,f],checks=[par('A','D','B','C'),ratio('A','D','A','C',1.5),ratio('A','C','B','C',1.5),ratio('D','C','A','B',1.5),ac(p,'D','A','C'),ac(p,'A','C','B')],notes=['Используется школьное определение трапеции: ровно одна пара противоположных сторон параллельна. Для параллелограмма условие о подобии само по себе не даёт требуемого равенства.'])

