def altitude_pair(x=2,y=5):
 p=dict(A=[0,0],B=[x,y],C=[8,0],H=[x,0]);pair(p,.65,(13,0));return p
p=altitude_pair();v=sc(list(p),tri()+tri(['A1','B1','C1'])+[['B','H'],['B1','H1']],rightAngles=[rt('B','H','A'),rt('B1','H1','A1')],angleArcs=[arc('A','B','C',1),arc('A1','B1','C1',1)])
f=more(v,polygons=[list('ABH'),['A1','B1','H1']])
q=altitude_pair(-3,5);w=more(v,dashSegments=[['H','A'],['H1','A1']])
q2=dict(A=[0,0],B=[0,5],C=[8,0]);pair(q2,.65,(12,0));w2=sc(list(q2),tri()+tri(['A1','B1','C1']),rightAngles=[rt('B','A','C'),rt('B1','A1','C1')])
add(719,'б','Докажите, что ABC и A₁B₁C₁ подобны, если ∠A =∠A₁ и AC/A₁C₁ =BH/B₁H₁, где BH и B₁H₁ — высоты треугольников.','△ABC ∼△A₁B₁C₁; основания высот могут лежать на продолжениях сторон.',[
 R('Как высота связана со стороной AB?','Если угол A острый, прямоугольные ABH и A₁B₁H₁ имеют равные углы при A и A₁. Если A тупой, их острые углы равны 180°−∠A и 180°−∠A₁. В обоих случаях треугольники подобны и AB/A₁B₁ =BH/B₁H₁. Положение H за C не меняет рассуждения.','Первый признак подобия; высота к прямой стороны.',66),
 R('Что происходит при прямом угле A?','Тогда H =A, H₁ =A₁, то есть BH =AB и B₁H₁ =A₁B₁. То же отношение AB/A₁B₁ =BH/B₁H₁ верно непосредственно, без вырожденных вспомогательных треугольников.','Определение высоты.',17),
 R('Какой признак применить к ABC?','Во всех случаях AB/A₁B₁ =BH/B₁H₁ =AC/A₁C₁, а заключённые между AB,AC и A₁B₁,A₁C₁ углы равны по условию. Поэтому △ABC ∼△A₁B₁C₁ по второму признаку.','Второй признак подобия.',67)],p,v,[f,v,v],checks=simchecks('A','B','C','A1','B1','C1',1/.65)+[ratio('B','H','B1','H1',1/.65),perp('B','H','A','C'),perp('B1','H1','A1','C1'),col('A','H','C'),col('A1','H1','C1')],cases=[(q,w,'Тупой угол A: высоты на продолжениях',1,[perp('B','H','A','C'),perp('B1','H1','A1','C1'),ratio('B','H','B1','H1',1/.65)]),(q2,w2,'Прямой угол A: высоты совпали со сторонами',2,[perp('A','B','A','C'),perp('A1','B1','A1','C1')])],offsets={'H':[0,5],'H1':[0,5]})

p=dict(A=[0,0],B=[6,0],D=[0,4],C=[8/3,4],H=[8/3,0]);p['O']=inter(p['A'],p['C'],p['B'],p['D'])
v=sc('ABCDO',poly()+[['A','C'],['B','D']],rightAngles=[rt('B','A','D'),rt('A','O','B')]);f=more(v,rightAngles=v['rightAngles']+[rt('A','D','C')],angleArcs=[arc('B','A','D',1),arc('A','D','C',1)])
g=more(f,'H',[['C','H']],rightAngles=f['rightAngles']+[rt('C','H','B')])
add(720,'single','В прямоугольной трапеции ABCD с прямым углом A диагонали взаимно перпендикулярны. Основание AB равно6 см, боковая сторона AD —4 см. Найдите DC, DB и CB.','DC =8/3 см; DB =2√13 см; CB =2√61/3 см.',[
 R('Какие прямоугольные треугольники подобны?','AB ∥DC и AD ⟂AB, значит AD ⟂DC. Из AB ⟂AD и BD ⟂AC следует ∠ABD =∠DAC. Поэтому △BAD ∼△ADC: B соответствует A, A — D, D — C.','Углы между попарно перпендикулярными прямыми; первый признак подобия.',66),
 R('Как найти второе основание?','Из подобия BA/AD =AD/DC. Значит DC =AD²/AB =16/6 =8/3 см.','Пропорциональность сходственных сторон.',64),
 R('Как найти диагональ DB?','В прямоугольном BAD: DB² =BA² +AD² =36+16 =52. Поэтому DB =2√13 см.','Теорема Пифагора.',60),
 R('Как найти боковую сторону CB?','Опустим CH на AB. Тогда AH =DC, CH =AD =4, а BH =AB−DC =6−8/3 =10/3. По теореме Пифагора CB² =BH²+CH² =(10/3)²+4² =244/9, откуда CB =2√61/3 см.','Теорема Пифагора для проекций боковой стороны.',60)],p,v,[f,f,f,g],checks=[par('A','B','D','C'),perp('A','D','A','B'),perp('A','D','D','C'),perp('A','C','B','D'),ratio('A','B','A','D',1.5),ratio('A','D','D','C',1.5),ratio('D','B','A','D',math.sqrt(13)/2),ratio('C','B','A','D',math.sqrt(61)/6),col('A','H','B'),perp('C','H','A','B'),equal(('A','H'),('D','C')),equal(('C','H'),('A','D'))],offsets={'O':[3,-3],'H':[0,5]})

def cross_trap(a=9,b=4,h=5,left=2):
 p=trap(a,b,h,left);p['O']=inter(p['A'],p['C'],p['B'],p['D']);t=p['O'][1]/h
 p['E']=mix(p['A'],p['B'],t);p['F']=mix(p['D'],p['C'],t);return p
p=cross_trap();v=sc('ABCDEFO',poly()+[['A','C'],['B','D'],['E','F']]);f=more(v,polygons=[list('ADO'),list('CBO')]);g=more(v,polygons=[list('AOE'),list('ACB')]);h=more(v,polygons=[list('DOF'),list('DBC')])
add(721,'single','Отрезок с концами на боковых сторонах трапеции параллелен основаниям и проходит через пересечение её диагоналей. Найдите его длину, если основания равны a и b.','2ab/(a+b). Точка пересечения диагоналей делит этот отрезок пополам.',[
 R('В каком отношении O делит диагональ?','Пусть AD =a, BC =b, O — пересечение диагоналей, E на AB, F на CD, EF ∥AD. По двум углам △AOD ∼△COB, поэтому AO/OC =a/b и AO/AC =a/(a+b). Так же DO/DB =a/(a+b).','Первый признак подобия; переход от отношения частей к доле целого.',[63,66]),
 R('Чему равна EO?','В △ACB отрезок EO параллелен CB. Поэтому △AOE ∼△ACB и EO/CB =AO/AC =a/(a+b). Отсюда EO =ab/(a+b).','Первый признак подобия.',66),
 R('Чему равна OF и весь отрезок?','В △DBC имеем OF ∥BC. Поэтому OF/BC =DO/DB =a/(a+b), откуда OF =ab/(a+b). Складывая EO и OF, получаем EF =2ab/(a+b).','Первый признак подобия и сложение отрезков.',66)],p,v,[f,g,h],checks=[par('A','D','B','C'),par('E','F','A','D'),col('A','O','C'),col('B','O','D'),col('A','E','B'),col('C','F','D'),col('E','O','F'),ratio('A','O','O','C',9/4),ratio('D','O','O','B',9/4),ratio('E','O','B','C',9/13),ratio('O','F','B','C',9/13),equal(('E','O'),('O','F'))],offsets={'E':[-3,1],'O':[0,-4],'F':[3,1]})

p=dict(A=[2,5],B=[0,0],C=[8,0],M=[1,2.5],N=[5,2.5],H=[2,0],K=[2,2.5],E=[0,2.5],F=[8,2.5])
v=sc('ABCMN',tri()+[['M','N']],equalSegments=[eq('A','M'),eq('M','B'),eq('A','N',2),eq('N','C',2)],lines=[['M','N']]);f=more(v,'HK',[['A','H']],rightAngles=[rt('A','H','B'),rt('A','K','M')]);g=more(f,'EF',[['B','E'],['C','F']],rightAngles=f['rightAngles']+[rt('B','E','M'),rt('C','F','N')]);h=more(g,equalSegments=v['equalSegments']+[eq('A','K',3),eq('B','E',3),eq('C','F',3)])
add(722,'single','Докажите, что вершины треугольника равноудалены от прямой, содержащей его среднюю линию.','Каждое расстояние равно половине высоты к третьей стороне.',[
 R('С какой стороной параллельна средняя линия?','Пусть M и N — середины AB и AC. Тогда MN ∥BC. Проведём высоту AH к прямой BC и обозначим K =AH ∩MN.','Теорема о средней линии.',69),
 R('Чему равно расстояние от A до MN?','Если H ≠B, в треугольнике ABH прямая MK параллельна BH и проходит через середину AB, поэтому AK =KH =AH/2. Если H =B, то K =M — середина AB, и то же равенство верно сразу. Перпендикуляр AH к BC перпендикулярен и MN. Значит расстояние от A до MN равно AH/2. Это верно и при H на продолжении BC.','Подобие в отношении1/2; отдельный случай прямого угла B; расстояние до прямой.',[37,66,69]),
 R('Каковы расстояния от B и C?','Перпендикуляры BE и CF к MN соединяют параллельные прямые BC и MN. Их длины равны расстоянию между этими прямыми, то есть KH =AH/2. Поэтому AK =BE =CF. Основания E,F могут лежать вне отрезка MN: речь именно о прямой.','Расстояние между параллельными прямыми.',37)],p,v,[f,g,h],checks=[equal(('A','M'),('M','B')),equal(('A','N'),('N','C')),par('M','N','B','C'),col('A','K','H'),col('E','M','K','N','F'),perp('A','H','B','C'),perp('B','E','M','N'),perp('C','F','M','N'),equal(('A','K'),('K','H'),('B','E'),('C','F'))],offsets={'M':[-2,-4],'K':[2,5],'E':[-3,1],'F':[3,1],'H':[0,5]})

p=dict(A=[-5,0],B=[0,3],C=[5,0],D=[0,-3],O=[0,0]);p.update(E=mid(p['A'],p['B']),F=mid(p['B'],p['C']),G=mid(p['C'],p['D']),H=mid(p['D'],p['A']))
v=sc('ABCDEFGH',poly(),equalSegments=[eq('A','B'),eq('B','C'),eq('C','D'),eq('D','A')]);f=more(v,segs=poly('EFGH'));g=more(f,'O',[['A','C'],['B','D']],rightAngles=[rt('A','O','B')]);h=more(g,rightAngles=g['rightAngles']+[rt('E','F','G')])
add(723,'single','Докажите, что середины сторон ромба являются вершинами прямоугольника.','Четырёхугольник середин сторон — прямоугольник.',[
 R('Как соединить середины?','Пусть E,F,G,H — середины AB,BC,CD,DA ромба. По теореме о средней линии EF ∥AC, GH ∥AC, FG ∥BD и HE ∥BD.','Средние линии четырёх треугольников.',69),
 R('Какая фигура получается?','EF ∥GH и FG ∥HE, поэтому EFGH — параллелограмм. Диагонали AC и BD ромба перпендикулярны.','Определение параллелограмма; свойство диагоналей ромба.',[48,52]),
 R('Почему это прямоугольник?','Так как EF ∥AC, FG ∥BD и AC ⟂BD, угол EFG прямой. Параллелограмм с прямым углом является прямоугольником.','Признак прямоугольника.',51)],p,v,[f,g,h],checks=[equal(('A','B'),('B','C'),('C','D'),('D','A')),equal(('A','E'),('E','B'),('B','F'),('F','C'),('C','G'),('G','D'),('D','H'),('H','A')),col('A','E','B'),col('B','F','C'),col('C','G','D'),col('D','H','A'),par('E','F','A','C'),par('G','H','A','C'),par('F','G','B','D'),par('H','E','B','D'),perp('A','C','B','D'),perp('E','F','F','G')],offsets={'E':[-3,-2],'F':[3,-2],'G':[3,3],'H':[-3,3]})

p=parallelogram(8,math.sqrt(20),math.degrees(math.atan2(4,2)));p.update(M=mid(p['C'],p['D']),N=mid(p['B'],p['C']));p['P']=inter(p['A'],p['N'],p['B'],p['D']);p['Q']=inter(p['A'],p['M'],p['B'],p['D'])
v=sc('ABCDMN',poly()+[['A','M'],['A','N'],['B','D']],equalSegments=[eq('C','M'),eq('M','D'),eq('B','N',2),eq('N','C',2)]);f=more(v,'P',polygons=[list('BPN'),list('DPA')]);g=more(f,'Q',polygons=[list('DQM'),list('BQA')]);h=more(g,equalSegments=v['equalSegments']+[eq('B','P',3),eq('P','Q',3),eq('Q','D',3)])
add(724,'single','M и N — середины CD и BC параллелограмма ABCD. Докажите, что прямые AM и AN делят диагональ BD на три равные части.','Если P =AN ∩BD, Q =AM ∩BD, то BP =PQ =QD =BD/3.',[
 R('Как найти положение P?','BN =BC/2 =AD/2. Треугольники BPN и DPA подобны по двум углам: BP и DP лежат на BD, PN и PA — на AN, BN ∥DA. Поэтому BP/PD =BN/DA =1/2, то есть BP =BD/3.','Свойства параллелограмма и первый признак подобия.',[48,66]),
 R('Как найти положение Q?','DM =DC/2 =AB/2. Треугольники DQM и BQA подобны: DQ и BQ лежат на BD, QM и QA — на AM, DM ∥BA. Значит DQ/QB =DM/BA =1/2 и DQ =BD/3.','Первый признак подобия.',66),
 R('Почему средняя часть тоже равна трети?','Вдоль BD точки идут B,P,Q,D: BP =BD/3, BQ =2BD/3. Поэтому PQ =BQ−BP =BD/3. Все три части равны.','Сложение и вычитание длин на одной диагонали.',63)],p,v,[f,g,h],checks=para_checks()+[equal(('C','M'),('M','D')),equal(('B','N'),('N','C')),col('B','P','Q','D'),col('A','P','N'),col('A','Q','M'),ratio('B','P','P','D',.5),ratio('D','Q','Q','B',.5),equal(('B','P'),('P','Q'),('Q','D'))],offsets={'P':[-3,-2],'Q':[3,2],'N':[0,-4],'M':[4,0]})

def external_bisector(b=5,c=3):
 p=dict(A=[0,0],B=[b,0],C=polar([0,0],60,c));p['D']=mix(p['B'],p['C'],b/(b-c));p['E']=foot(p['D'],p['A'],p['B']);p['F']=foot(p['D'],p['A'],p['C']);p['X']=[-3,0];return p
p=external_bisector();v=sc('ABCDX',tri()+[['A','D']],dashSegments=[['C','D'],['A','X']],angleArcs=[arc('A','X','D',1),arc('A','D','C',1)]);f=more(v,'EF',[['D','E'],['D','F']],dashSegments=v['dashSegments']+[['X','E'],['C','F']],rightAngles=[rt('D','E','A'),rt('D','F','A')]);g=more(f,equalSegments=[eq('D','E'),eq('D','F')])
q=external_bisector(3,5);w=sc('ABCDEF',tri()+[['A','D'],['D','E'],['D','F']],dashSegments=[['B','D'],['A','F'],['B','E']],rightAngles=[rt('D','E','A'),rt('D','F','A')],equalSegments=[eq('D','E'),eq('D','F')])
add(725,'single','Биссектриса внешнего угла при A треугольника ABC пересекает прямую BC в D. Докажите, что BD/AB =DC/AC.','BD/DC =AB/AC, или BD/AB =DC/AC; D лежит на продолжении BC.',[
 R('Какие расстояния от D равны?','Пусть DE и DF — перпендикуляры из D к прямым AB и AC. Точка биссектрисы внешнего угла равноудалена от его сторон: прямоугольные ADE и ADF равны по общей гипотенузе AD и равному острому углу. Поэтому DE =DF.','Свойство биссектрисы угла; равенство прямоугольных треугольников.',[17,35]),
 R('Как сравнить площади по основаниям AB и AC?','S(ABD) =AB·DE/2, S(ACD) =AC·DF/2. Из DE =DF следует S(ABD)/S(ACD) =AB/AC.','Площадь треугольника.',58),
 R('Как сравнить те же площади по основаниям BD и DC?','Оба основания лежат на одной прямой BC, поэтому высота из A общая. Следовательно S(ABD)/S(ACD) =BD/DC. Приравнивая, получаем BD/DC =AB/AC и требуемое BD/AB =DC/AC.','Площадь треугольника и пропорции.',[58,63]),
 R('Всегда ли есть такая точка D?','Внешняя биссектриса не проходит через внутренность угла A, поэтому D не лежит внутри BC. Если AB >AC, D за C; если AB <AC, D за B. При AB =AC внешняя биссектриса параллельна BC и конечной точки D нет: этот случай исключён условием о пересечении.','Положение внешней биссектрисы и свойство равнобедренного треугольника.',18)],p,v,[f,g,g,g],checks=[col('B','C','D'),col('A','B','E','X'),col('A','F','C'),perp('D','E','A','B'),perp('D','F','A','C'),equal(('D','E'),('D','F')),ratio('B','D','D','C',5/3),ratio('A','B','A','C',5/3),ac(p,'X','A','D'),ac(p,'D','A','C')],cases=[(q,w,'AB <AC: точка D за B',4,[col('B','C','D'),ratio('B','D','D','C',3/5),equal(('D','E'),('D','F')),perp('D','E','A','B'),perp('D','F','A','C')])],offsets={'E':[-3,4],'F':[3,-2],'X':[0,5],'A':[2,4]})

def midpoint_bisector(b=7,c=4):
 p=dict(A=[0,0],B=polar([0,0],30,b),C=polar([0,0],-30,c));p['M']=mid(p['B'],p['C']);p['D']=polar(p['A'],30,(b-c)/2);p['E']=polar(p['A'],-30,(c-b)/2);p['L']=mix(p['B'],p['C'],b/(b+c));p['F']=polar(p['A'],30,-c);p['G']=polar(p['A'],-30,-b);return p
p=midpoint_bisector();v=sc('ABCDEML',tri()+[['D','M'],['E','M'],['A','L']],dashSegments=[['A','E']],equalSegments=[eq('B','M'),eq('M','C')],angleArcs=[arc('A','B','L',1),arc('A','L','C',1)])
f=more(v,'F',[['C','F']],dashSegments=v['dashSegments']+[['A','F']]);g=more(f,'G',[['B','G']],dashSegments=f['dashSegments']+[['A','G']]);q=midpoint_bisector(4,7);w=sc('ABCDEMLFG',tri()+[['D','M'],['E','M'],['A','L'],['C','F'],['B','G']],dashSegments=[['A','F'],['A','G']],equalSegments=[eq('B','D'),eq('C','E')])
add(726,'single','В треугольнике ABC, AB ≠AC, через середину BC проведена прямая, параллельная биссектрисе угла A; она пересекает прямые AB и AC в D и E соответственно. Докажите, что BD =CE.','BD =CE =(AB+AC)/2. Пересечения с продолжениями сторон учитываются.',[
 R('Как добавить удобный равнобедренный треугольник?','Обозначим середину BC через M, биссектрису — AL. Через C проведём CF ∥AL до пересечения с прямой AB. F лежит на луче, противоположном AB. Углы ACF и AFC равны половине ∠A, поэтому AF =AC.','Параллельные прямые и признак равнобедренного треугольника.',[18,25]),
 R('Почему D — середина BF?','В треугольнике BCF точка M — середина BC, а MD ∥CF. По обратному применению теоремы о средней линии D — середина BF. Так как A между B и F, BF =AB+AF =AB+AC, поэтому BD =(AB+AC)/2.','Первый признак подобия с коэффициентом1/2.',[66,69]),
 R('Как получить такую же длину CE?','Через B проведём BG ∥AL до прямой AC. Треугольник ABG равнобедренный: AG =AB, причём A между C и G. В треугольнике CBG отрезок ME параллелен BG и проходит через середину CB, значит E — середина CG. Поэтому CE =CG/2 =(AC+AB)/2 =BD.','Та же средняя линия и равенство углов при параллельных прямых.',[25,69]),
 R('Где лежат D и E?','Если AB >AC, D лежит внутри AB, а E — на продолжении AC за A. Если AB <AC, положение меняется: D за A, E внутри AC. Условие AB ≠AC исключает совпадение D =E =A. В обоих допустимых случаях доказательство одинаково.','Уточнение слова «прямые» в условии; найденные половины BF и CG.',63)],p,v,[f,f,g,g],checks=[equal(('B','M'),('M','C')),par('D','E','A','L'),par('C','F','A','L'),par('B','G','A','L'),col('B','D','A','F'),col('C','A','E','G'),col('D','E','M'),equal(('A','F'),('A','C')),equal(('A','G'),('A','B')),equal(('B','D'),('D','F'),('C','E'),('E','G')),ac(p,'B','A','L'),ac(p,'L','A','C')],cases=[(q,w,'AB <AC: D на продолжении, E на стороне',4,[col('B','D','A','F'),col('C','A','E','G'),equal(('B','D'),('C','E')),par('D','E','A','L')])],offsets={'D':[1,-4],'E':[-2,3],'A':[0,5],'L':[3,0],'M':[3,0]})

