add(729,'single','В прямоугольной трапеции ABCD с основаниями AD и BC: ∠A =∠B =90°, ∠ACD =90°, BC =4 см, AD =16 см. Найдите углы C и D.','∠C =150°, ∠D =30°.',[
 R('Как связать диагональ с основаниями?','Проведём CH ⟂AD. ABCH — прямоугольник, поэтому AH =BC =4 см. В прямоугольном ACD катет AC удовлетворяет AC² =AD·AH =16·4 =64, значит AC =8 см.','Катет есть среднее пропорциональное гипотенузы и его проекции.',71),
 R('Чему равен угол D?','В прямоугольном ACD: sin∠D =AC/AD =8/16 =1/2. Поскольку ∠D острый, ∠D =30°.','Значение синуса30° и однозначность острого угла по синусу.',[74,75]),
 R('Как найти угол C трапеции?','AD ∥BC, поэтому внутренние односторонние углы при стороне CD дают ∠C+∠D =180°. Значит ∠C =150°. Угол ACD =90° — лишь часть угла BCD.','Свойство параллельных прямых.',25)],p,v,[f,g,g],checks=[par('A','D','B','C'),perp('A','B','A','D'),perp('A','B','B','C'),perp('A','C','C','D'),perp('C','H','A','D'),equal(('A','H'),('B','C')),ratio('A','H','A','D',.25),ratio('A','C','A','D',.5),ang('A','D','C',30),ang('B','C','D',150)],offsets={'H':[0,5],'C':[2,-4]})

