add(731,'single','Основание AD равнобедренной трапеции ABCD в5 раз больше BC. Высота BH пересекает AC в M. Площадь AMH равна4 см². Найдите площадь трапеции ABCD.','18 см².',[
 R('Как выразить AH через меньшее основание?','Пусть BC =b, AD =5b, BH =h. В равнобедренной трапеции выступы большого основания равны, поэтому AH =(AD−BC)/2 =2b.','Свойства равнобедренной трапеции; равные прямоугольные треугольники у концов основания.',[35,50]),
 R('Какую часть высоты составляет MH?','△AMH ∼△CMB: прямые углы при H и B, вертикальные углы при M. Поэтому MH/MB =AH/CB =2. Так как MH+MB =h, получаем MH =2h/3.','Первый признак подобия.',66),
 R('Как использовать площадь4?','S(AMH) =AH·MH/2 =(2b)(2h/3)/2 =2bh/3 =4. Поэтому bh =6 см².','Площадь прямоугольного треугольника.',58),
 R('Какова площадь всей трапеции?','S(ABCD) =(AD+BC)h/2 =(5b+b)h/2 =3bh =18 см².','Площадь трапеции.',59)],p,v,[v,f,f,f],checks=[par('A','D','B','C'),equal(('A','B'),('C','D')),ratio('A','D','B','C',5),ratio('A','H','B','C',2),ratio('M','H','M','B',2),perp('B','H','A','D'),col('A','M','C'),col('B','M','H')],offsets={'M':[3,2],'H':[0,5],'B':[-3,-3],'A':[-3,2],'C':[2,-3]})

