add(732,'single','Докажите, что ABC и A₁B₁C₁ подобны, если AB/A₁B₁ =AC/A₁C₁ =AD/A₁D₁, где AD и A₁D₁ — биссектрисы треугольников.','△ABC ∼△A₁B₁C₁.',[
 R('Как построить вспомогательные равнобедренные треугольники?','На луче, противоположном AB, возьмём E с AE =AC. Аналогично A₁E₁ =A₁C₁ на противоположном A₁B₁ луче. В равнобедренном AEC угол EAC =180°−∠A, поэтому оба угла при основании EC равны ∠A/2. Отсюда EC ∥AD. Аналогично E₁C₁ ∥A₁D₁.','Углы равнобедренного треугольника и признак параллельности.',[18,24]),
 R('Как выразить вспомогательное основание EC?','Так как AD ∥EC, △BAD ∼△BEC. Поэтому AD/EC =BA/BE. При BE =AB+AC получаем EC =AD·(AB+AC)/AB. Аналогично E₁C₁ =A₁D₁·(A₁B₁+A₁C₁)/A₁B₁.','Первый признак подобия.',66),
 R('Что дают три исходных отношения?','Пусть каждое равно k. Тогда AB =kA₁B₁, AC =kA₁C₁, AD =kA₁D₁. Подстановка в найденную формулу даёт EC =kE₁C₁. Кроме того, AE =AC =kA₁C₁ =kA₁E₁. Значит все три стороны AEC и A₁E₁C₁ пропорциональны с коэффициентом k.','Алгебра пропорций.',63),
 R('Как получить равенство исходных углов?','По третьему признаку △AEC ∼△A₁E₁C₁. Следовательно ∠EAC =∠E₁A₁C₁. Это дополнительные к ∠A и ∠A₁ углы, поэтому ∠A =∠A₁.','Третий признак подобия; смежные углы.',[12,68]),
 R('Как завершить доказательство?','У исходных треугольников AB/A₁B₁ =AC/A₁C₁ и равны углы между этими сторонами. Поэтому △ABC ∼△A₁B₁C₁ по второму признаку.','Второй признак подобия.',67)],p,v,[f,f,g,g,g],checks=simchecks('A','B','C','A1','B1','C1',1/.7)+[ratio('A','D','A1','D1',1/.7),ratio('E','C','E1','C1',1/.7),equal(('A','E'),('A','C')),equal(('A1','E1'),('A1','C1')),col('E','A','B'),col('E1','A1','B1'),col('B','D','C'),col('B1','D1','C1'),par('E','C','A','D'),par('E1','C1','A1','D1'),ac(p,'B','A','D'),ac(p,'D','A','C')],offsets={'A':[0,5],'A1':[0,5],'D':[3,0],'D1':[3,0]})

