add(736,'single','Постройте треугольник по стороне и медианам, проведённым к двум другим сторонам.','Для BC =a, медиан BN =mᵦ и CM =m𝚌: построить BG =2mᵦ/3, CG =2m𝚌/3; K — середина BC, A на луче KG с GA =2GK. Решение есть ровно при |2mᵦ/3−2m𝚌/3| <a <2mᵦ/3+2m𝚌/3.',[
 R('Какие длины сначала построить?','Пусть данная сторона — BC =a, а медианы к AC и AB равны mᵦ и m𝚌. Построим r =2mᵦ/3 и s =2m𝚌/3. Для деления отрезка UV на три части проведём из U вспомогательный луч, отложим на нём циркулем три равных шага UR₁ =R₁R₂ =R₂R₃, соединим R₃ с V и проведём через R₂ параллельную R₃V. Её пересечение T с UV даст UT =2UV/3. Повторим для обоих данных отрезков.','Теорема Фалеса или подобие; построение параллельной прямой переносом угла.',[24,66]),
 R('Как построить предполагаемый центроид?','Отложим циркулем BC =a. Проведём окружность с центром B радиуса r и окружность с центром C радиуса s. Их общая точка G должна стать центроидом, поскольку центроид делит медиану в отношении2 :1 от вершины.','Построение окружностей; свойство медиан.',[21,69,70]),
 R('Как выбрать G?','Если окружности пересекаются в двух точках, выберем любую из них и соединим G с B и C. Получим невырожденный треугольник BGC со сторонами a,r,s. Две точки пересечения дают зеркальные решения.','Построение треугольника по трём сторонам.',23),
 R('Как восстановить вершину A?','Построим середину K отрезка BC с помощью серединного перпендикуляра. На луче KG за G отложим циркулем два последовательных отрезка длиной KG; конечную точку назовём A. Тогда GA =2GK и KA =3KG. Соединим A с B и C.','Построение середины отрезка и перенос длины циркулем.',21),
 R('Почему получены именно заданные медианы?','K — середина BC, так что AK — медиана построенного ABC. Его настоящий центроид лежит на AK и делит её в отношении2 :1 от A; это единственная точка G, построенная нами. Поэтому G принадлежит также медианам BN и CM. Значит BN =3BG/2 =3r/2 =mᵦ, CM =3CG/2 =3s/2 =m𝚌. На чертеже M и N появляются только после построения ABC.','Единственность центроида и отношение2 :1 на каждой медиане.',[69,70]),
 R('Как исследовать существование и число решений?','Положительные a,mᵦ,m𝚌 дают невырожденный BGC ровно при |r−s| <a <r+s. Это и есть необходимое и достаточное условие. При равенстве окружности касаются, G лежит на BC и ABC вырождается; при нарушении неравенств общего G нет. При строгих неравенствах есть два расположения, симметричные относительно BC; с точностью до равенства треугольников решение одно.','Неравенство треугольника; взаимное расположение двух окружностей.',[23,34,72])],p,v,[f,g,h,j,k,k],checks=[equal(('B','G'),('_mb0','_mb2')),equal(('C','G'),('_mc0','_mc2')),ratio('_mb0','_mb2','_mb0','_mb3',2/3),ratio('_mc0','_mc2','_mc0','_mc3',2/3),equal(('B','K'),('K','C')),col('B','K','C'),col('K','G','A'),ratio('A','G','G','K',2),equal(('A','M'),('M','B')),equal(('A','N'),('N','C')),col('B','G','N'),col('C','G','M'),ratio('B','G','B','N',2/3),ratio('C','G','C','M',2/3),equal(('B','N'),('_mb0','_mb3')),equal(('C','M'),('_mc0','_mc3')),equal(('B','G'),('B','_rb')),equal(('C','G'),('C','_rc'))],cases=[(q3,w3,'Как построить две трети данного отрезка',1,[equal(('U','R1'),('R1','R2'),('R2','R3')),col('U','R1','R2','R3'),col('U','T','V'),par('R2','T','R3','V'),ratio('U','T','U','V',2/3)]),(q,w,'Второе зеркальное решение',6,[col('K','G','A'),ratio('A','G','G','K',2),ratio('B','G','B','N',2/3),ratio('C','G','C','M',2/3)]),(q2,w2,'Граница r+s =a: треугольника нет',6,[col('B','G','C'),equal(('B','G'),('B','_r')),equal(('C','G'),('C','_s'))])],labels={'mb':'mᵦ','mc':'m𝚌'},offsets={'B':[-2,4],'C':[2,4],'K':[0,5],'G':[3,-1],'M':[-3,0],'N':[3,0],'A':[-2,-4],'mb':[0,-3],'mc':[0,-3]},notes=['Данные медианы относятся к двум сторонам, отличным от заданной BC. Несуществующие и вырожденные входы не изображаются как допустимые треугольники.'])
