# Show736 as three legible phases.  The canonical coordinates above remain the
# numerical oracle; each phase is an exact similarity, with independent checks
# copied only when every referenced point belongs to that phase.  Given lengths
# stay available in their own view after their copying is complete.
model=B.models[-1]['model'];canonical_checks=deepcopy(model['checks'])
def phase(raw,views,suffix,offsets=None):
 names={name:name+'__'+suffix for name in raw}
 def rename(obj):
  if isinstance(obj,str):return names.get(obj,obj)
  if isinstance(obj,list):return [rename(x) for x in obj]
  if isinstance(obj,dict):return {key:rename(x) for key,x in obj.items()}
  return obj
 points=normalize(raw,list(views.values()))
 model['points'].update({names[name]:[xyz[0],round(80-xyz[1],9),0] for name,xyz in points.items()})
 for name in raw:
  if not name.startswith('_'):model['labels'][names[name]]={'mb':'mᵦ','mc':'m𝚌'}.get(name,name)
 for name,offset in (offsets or {}).items():model['labelOffsets'][names[name]]=offset
 for key,view in views.items():model['views'][key]=rename(view)
 for name in ['mb','mc']:
  if name in names:model['labelOnly'].append(names[name])
 def refs(obj):
  if isinstance(obj,str):return {obj} if obj in p else set()
  if isinstance(obj,list):return set().union(*(refs(x) for x in obj))
  if isinstance(obj,dict):return set().union(*(refs(x) for x in obj.values()))
  return set()
 for check in canonical_checks:
  if refs(check) and refs(check)<=set(raw):model['checks'].append(rename(check))
 return names
given_names=['B','C','mb','mc','_mb0','_mb1','_mb2','_mb3','_mc0','_mc1','_mc2','_mc3']
